lesson.code_example:
public class Car {
    String color;
    int speed;

    public void accelerate() {
        speed += 10;
    }

    public static void main(String[] args) {
        Car myCar = new Car();
        myCar.color = "Red";
        myCar.speed = 0;
        myCar.accelerate();
        System.out.println("Car color: " + myCar.color + ", Speed: " + myCar.speed); // Outputs Red, Speed: 10
    }
}

